import { useState } from 'react';
import {
  Table, Tag, Space, Typography, Select, Drawer, Button, Form, Input, App as AntApp, Descriptions,
} from 'antd';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api, getErrorMessage } from '../../lib/api';
import { RequestStatus } from '@phison/types';
import type { ResidentRequest } from '@phison/types';
import { formatDateTime } from '../../lib/formatters';

const { Title } = Typography;

const STATUS_COLORS: Record<string, string> = {
  submitted: 'orange', acknowledged: 'blue', in_progress: 'cyan',
  resolved: 'green', closed: 'default', rejected: 'red',
};

export default function RequestsAdminPage() {
  const { message } = AntApp.useApp();
  const qc = useQueryClient();
  const [statusFilter, setStatusFilter] = useState<string | undefined>();
  const [selected, setSelected] = useState<ResidentRequest | null>(null);
  const [statusForm] = Form.useForm();

  const { data: requests = [], isLoading } = useQuery({
    queryKey: ['requests', statusFilter],
    queryFn: () =>
      api.get<ResidentRequest[]>(`/requests${statusFilter ? `?status=${statusFilter}` : ''}`).then(r => r.data),
  });

  const statusMutation = useMutation({
    mutationFn: (v: { status: string; comment?: string }) =>
      api.patch(`/requests/${selected?.id}/status`, v),
    onSuccess: () => {
      message.success('Status updated');
      qc.invalidateQueries({ queryKey: ['requests'] });
      statusForm.resetFields();
    },
    onError: (e) => message.error(getErrorMessage(e)),
  });

  const columns = [
    { title: 'Subject', dataIndex: 'subject', key: 'subject' },
    { title: 'Category', dataIndex: 'category', key: 'category', render: (c: string) => <Tag>{c}</Tag> },
    { title: 'Unit', dataIndex: 'unitId', key: 'unitId' },
    {
      title: 'Status', dataIndex: 'status', key: 'status',
      render: (s: string) => <Tag color={STATUS_COLORS[s]}>{s.replace(/_/g, ' ')}</Tag>,
    },
    { title: 'Created', dataIndex: 'createdAt', key: 'createdAt', render: formatDateTime },
    {
      title: 'Actions', key: 'actions',
      render: (_: unknown, record: ResidentRequest) => (
        <Button size="small" onClick={() => setSelected(record)}>Manage</Button>
      ),
    },
  ];

  return (
    <Space direction="vertical" size={16} style={{ width: '100%' }}>
      <Space style={{ justifyContent: 'space-between', width: '100%' }}>
        <Title level={4} style={{ margin: 0 }}>Resident Requests</Title>
        <Select
          allowClear
          placeholder="Filter by status"
          style={{ width: 200 }}
          onChange={setStatusFilter}
          options={Object.values(RequestStatus).map(s => ({ label: s.replace(/_/g, ' '), value: s }))}
        />
      </Space>

      <Table dataSource={requests} columns={columns} rowKey="id" loading={isLoading} />

      <Drawer
        title={selected?.subject}
        open={!!selected}
        onClose={() => setSelected(null)}
        width={480}
      >
        {selected && (
          <Space direction="vertical" size={24} style={{ width: '100%' }}>
            <Descriptions column={1} size="small">
              <Descriptions.Item label="Category">{selected.category}</Descriptions.Item>
              <Descriptions.Item label="Status">
                <Tag color={STATUS_COLORS[selected.status]}>{selected.status}</Tag>
              </Descriptions.Item>
              <Descriptions.Item label="Description">{selected.description}</Descriptions.Item>
            </Descriptions>

            <Form form={statusForm} layout="vertical" onFinish={v => statusMutation.mutate(v)}>
              <Typography.Text strong>Update Status</Typography.Text>
              <Form.Item name="status" rules={[{ required: true }]} style={{ marginTop: 8 }}>
                <Select
                  options={Object.values(RequestStatus).map(s => ({ label: s.replace(/_/g, ' '), value: s }))}
                />
              </Form.Item>
              <Form.Item name="comment">
                <Input placeholder="Optional comment" />
              </Form.Item>
              <Button type="primary" htmlType="submit" loading={statusMutation.isPending} block>
                Update Status
              </Button>
            </Form>
          </Space>
        )}
      </Drawer>
    </Space>
  );
}
